#!/bin/bash
# Rename Chinese filenames to English

rename_file() {
  local old="$1"
  local new="$2"
  if [ -f "$old" ]; then
    git mv "$old" "$new"
  fi
}

rename_dir() {
  local old="$1"
  local new="$2"
  if [ -d "$old" ]; then
    git mv "$old" "$new"
  fi
}

